        {Test t(root/"usb");const auto result=t.apply();check(result["applied"]==true&&result["activation"]=="next_open"&&result["updated_targets"].size()==1&&!result["source_on_sd"].get<bool>(),"USB self-update publishes compatible release");check(sha256(t.fixture.base/"manager")==t.staged["files"]["autorun/runtime/manager"]&&sha256(t.fixture.base/"font.ttf")==t.staged["files"]["autorun/runtime/font.ttf"],"next shortcut opening uses refreshed manager and font");t.preserved();}
        {Test t(root/"cached-licenses");const std::string name="autorun/runtime/licenses/plugin-manager-usb.txt";save(t.source/name,"previous license");auto old=Json::parse(read(t.source/"USB-SHA256.json"));old[name]=sha256(t.source/name);save(t.source/"USB-SHA256.json",old.dump(2)+'\n');for(const auto& item:old.items())if(item.key().rfind("autorun/runtime/licenses/",0)==0)save(t.fixture.base/item.key().substr(16),read(t.source/item.key()));t.apply();check(sha256(t.fixture.base/"licenses/plugin-manager-usb.txt")==t.staged["files"][name],"existing cached license data updates with the persistent release");}
        {Test t(root/"legacy");fs::remove_all(t.fixture.paths.helper);const auto result=t.apply();check(result["applied"]==true&&!fs::exists(t.fixture.paths.helper),"legacy USB update refreshes cache without creating a helper");t.preserved();}
        {Test t(root/"legacy-no-xpa");fs::remove_all(t.fixture.paths.helper);const auto update=fs::path(t.staged["bundle_root"].get<std::string>());fs::remove(update/"Plugin Manager helper.xpa");t.staged["files"].erase("Plugin Manager helper.xpa");save(update/"USB-SHA256.json",t.staged["files"].dump(2)+'\n');fs::remove(t.source/"Plugin Manager helper.xpa");auto old=Json::parse(read(t.source/"USB-SHA256.json"));old.erase("Plugin Manager helper.xpa");save(t.source/"USB-SHA256.json",old.dump(2)+'\n');check(t.apply()["applied"]==true,"legacy source and release without helper archive can self-update");}
        {Test t(root/"legacy-universal");fs::remove_all(t.fixture.paths.helper);fs::remove(t.source/"Plugin Manager helper.xpa");auto old=Json::parse(read(t.source/"USB-SHA256.json"));old.erase("Plugin Manager helper.xpa");save(t.source/"USB-SHA256.json",old.dump(2)+'\n');check(t.apply()["applied"]==true&&sha256(t.source/"Plugin Manager helper.xpa")==t.staged["files"]["Plugin Manager helper.xpa"]&&!fs::exists(t.fixture.paths.helper),"legacy USB can receive a universal bundle without importing its helper");}
        {Test t(root/"legacy-universal-rollback");fs::remove_all(t.fixture.paths.helper);fs::remove(t.source/"Plugin Manager helper.xpa");auto old=Json::parse(read(t.source/"USB-SHA256.json"));old.erase("Plugin Manager helper.xpa");save(t.source/"USB-SHA256.json",old.dump(2)+'\n');const auto before=t.snapshot();t.fixture.paths.beforePublish=[](size_t index){if(index==1)throw std::runtime_error("fixture write failure");};rejects([&]{t.apply();},"legacy universal upgrade failure rolls back");check(t.snapshot()==before&&!fs::exists(t.source/"Plugin Manager helper.xpa"),"rollback removes only the newly created helper archive");}
        {Test t(root/"sd");t.fixture.installSd();t.fixture.usbMounted=false;t.fixture.mounts();const auto result=applyManagerUpdate(t.fixture.selectSd(),t.session,t.staged,t.fixture.paths);check(result["source_on_sd"]==true&&result["updated_targets"].size()==1,"SD self-update succeeds without USB");const auto receipt=Json::parse(read(t.fixture.sd/".manager-install.json"));check(receipt["files"]["autorun/runtime/manager"]==t.staged["files"]["autorun/runtime/manager"]&&read(t.fixture.paths.helper/"runtime.sha256")==binding(t.staged["files"]),"SD receipt and helper binding match updated runtime");t.preserved();}
        {Test t(root/"both");t.fixture.installSd();const auto result=t.apply();check(result["updated_targets"].size()==2&&sha256(t.fixture.sd/"autorun/runtime/manager")==sha256(t.source/"autorun/runtime/manager"),"mounted USB and configured SD update coherently");t.preserved();}
        {Test t(root/"absent-other");t.fixture.installSd(false);const auto old=sha256(t.fixture.sd/"autorun/runtime/manager");const auto result=t.apply();check(result["configured_sd_absent"]==true&&result["updated_targets"].size()==1&&sha256(t.fixture.sd/"autorun/runtime/manager")==old,"absent configured media remains unchanged and is explicitly reported");}
        {Test t(root/"readonly-other");t.fixture.installSd();auto mounts=read(t.fixture.paths.mountinfo);const auto position=mounts.find(" rw - exfat /dev/fixture-sd");mounts.replace(position,4," ro ");save(t.fixture.paths.mountinfo,mounts);const auto before=t.snapshot();rejects([&]{t.apply();},"mounted read-only configured media blocks the shared-helper update");check(t.snapshot()==before,"read-only second source cannot be silently left incompatible");}
