        {Test t(root/"late-parent-swap");const auto runtime=t.source/"autorun/runtime",retained=t.source/"retained-runtime",outside=t.root/"protected";save(outside/"manager","protected manager");save(outside/"font.ttf","protected font");const auto original=read(runtime/"font.ttf");bool swapped=false;t.fixture.paths.beforeRename=[&](size_t index){if(index==1){fs::rename(runtime,retained);fs::create_directory_symlink(outside,runtime);swapped=true;}};rejects([&]{t.apply();},"late parent substitution is rejected");check(swapped&&read(outside/"manager")=="protected manager"&&read(outside/"font.ttf")=="protected font"&&read(retained/"font.ttf")==original,"pinned publication and rollback never follow a late parent symlink");}
